  eq(PT.monthlyRoll(PT.emptyProtestBook('1'), { ...E, atWar: false }, [{ k: 3, name: 'P3', stability: 30, factionShare: { militarist: 0.5 } }], 'd', seq(0), () => 'z', cause)?.demand.kind, 'stop_war_humiliation', 'event grievance feeds monthly roll');
