  const m = (kind: string, kv: Record<string, string>) => ({ kind, kv }) as never;
  t.feed(m('CONTACT_BEGIN', { sid: '5', n: '1', date: 'd' })); t.feed(m('CONTACT', { sid: '5', n: '1', idx: '1', name: 'B', rel: 'comm', score: '3', ct: '1' })); t.feed(m('CONTACT', { sid: '5', n: '1', idx: '2', name: 'A Civilian Fleet', rel: 'comm', score: '0', type: 'civilian_fleet', ct: '0' }));
  ok(t.feed(m('CONTACT_END', { sid: '5', n: '1' })), 'contacts done');
  eq([t.items.map((c) => c.idx), t.cut.map((c) => c.idx), t.all.length], [[1], [2], 2], 'cut contact leaves items (so every feature drops it) but stays in cut');
  cutSet.delete(2); t.refilter(); eq([t.items.map((c) => c.idx).sort(), t.cut.length], [[1, 2], 0], 'restore puts it back');
  t.reset(); eq([t.items.length, t.all.length, t.cut.length], [0, 0, 0], 'reset clears all lists');
  const root = pathP.join(__dirname, '..'), rd = (f: string) => fsP.readFileSync(pathP.join(root, f), 'utf8');
  const ta = rd('src/features/terminal.ts'), pr = rd('src/preload.ts'), ui = rd('ui/terminal-ui.js'), css = rd('ui/terminal-ui.css');
  ok(ta.includes("ipcMain.handle('contactCut'") && ta.includes("ipcMain.handle('contactRestore'") && ta.includes("'sllm_contact_cut.json'") && ta.includes('terminal.isCut = (sid, idx) =>') && ta.includes('cat: contactCategory(c.type)') && ta.includes('if (ctx.pend || ctx.pending) return'), 'app: cut/restore per save, saved to its own file, blocked during a call, categories sent');
